1131	type BlockDev = { name: string; type: string; sizeBytes: number; fstype: string; mount: string; pkname: string };
1132	
1133	/**
1134	 * A device path we are willing to hand to mkfs/mount/blkid: a whole disk such as
1135	 * `/dev/sdb` and nothing else — no partitions, no `..`, no shell metacharacters,
1136	 * no device-mapper aliases.
1137	 */
1138	const DEVPATH_RE = /^\/dev\/[a-z][a-z0-9]{1,31}$/;
1139	
1140	/** Read `df` free bytes for a path (GNU `--output`, with a portable fallback). */
1141	async function availBytes(conn: Client, path: string): Promise<number | null> {
1142	  const r = await sh(conn, `df -B1 --output=avail ${path} 2>/dev/null | tail -n1`);
1143	  let n = Number(clean(r.stdout, 32));
1144	  if (!Number.isFinite(n) || n <= 0) {
1145	    const r2 = await sh(conn, `df -B1 ${path} 2>/dev/null | awk 'NR==2{print $4}'`);
1146	    n = Number(clean(r2.stdout, 32));
1147	  }
1148	  return Number.isFinite(n) && n > 0 ? n : null;
1149	}
