1200	  if (ls.code !== 0) return [];
1201	  const rows = parseLsblk(ls.stdout);
1202	  if (!rows.length) return [];
1203	
1204	  const byName = new Map(rows.map((r) => [r.name, r]));
1205	  /** Walk PKNAME up to the top-level device (bounded — never trust a cycle). */
1206	  const topOf = (name: string): string => {
1207	    let cur = name;
1208	    for (let i = 0; i < 8; i++) {
1209	      const row = byName.get(cur);
1210	      if (!row?.pkname || row.pkname === cur) break;
1211	      cur = row.pkname;
1212	    }
1213	    return cur;
1214	  };
