1216	  // Any disk with a filesystem or a mountpoint ANYWHERE in its tree is out.
1217	  const inUse = new Set<string>();
1218	  for (const r of rows) if (r.fstype || r.mount) inUse.add(topOf(r.name));
1219	
1220	  // Belt and braces: never touch the disk that backs `/`, however it is stacked.
1221	  const rs = await sh(conn, `findmnt -n -o SOURCE / 2>/dev/null | head -n1`);
1222	  const rootSrc = clean(rs.stdout, 128);
1223	  if (/^\/dev\/[A-Za-z0-9/_-]{1,64}$/.test(rootSrc)) {
1224	    inUse.add(topOf(rootSrc.slice(rootSrc.lastIndexOf("/") + 1)));
