1258	    conn,
1259	    `blkid /dev/${name} >/dev/null 2>&1 && echo SIG; ` +
1260	      `findmnt -S /dev/${name} >/dev/null 2>&1 && echo MOUNTED; ` +
1261	      `[ -n "$(ls -A /sys/block/${name}/holders 2>/dev/null)" ] && echo HELD; ` +
1262	      `[ -n "$(lsblk -no NAME /dev/${name} 2>/dev/null | tail -n +2)" ] && echo CHILD; ` +
