1338	      continue;
1339	    }
1340	    await sh(conn, `mkdir -p ${dest} ${store}`);
1341	    const cp = await sh(conn, `rsync -a --numeric-ids ${store}/ ${dest}/ 2>&1`, TRANSFER_TIMEOUT_MS);
1342	    if (cp.code !== 0) {
1343	      failed.push(`${store}: copy failed (${tailOf(cp)})`);
1344	      continue;
1345	    }
1346	    await sh(
1347	      conn,
1348	      `grep -q " ${store} none bind" /etc/fstab || printf '%s %s none bind,nofail 0 0\\n' '${dest}' '${store}' >> /etc/fstab`
1349	    );
