1359	      failed.push(`${store}: bind mount failed (${tailOf(mnt)}) — left in place`);
1360	      continue;
1361	    }
1362	    await sh(conn, `rm -rf ${store}.premigrate 2>/dev/null; true`, SETUP_TIMEOUT_MS);
