 *   VOLUME_DELETE: volumeDelete,
 *
 * Ownership + validation are enforced at enqueue time (lib/actions-volumes.ts),
 * so these handlers trust `payload.volumeId` / `payload.targetServerId`.
 *
 * A volume's underlying Proxmox disk only exists once it has been attached at
 * least once. `Volume.diskName` stores the STABLE Proxmox volume id of that disk
 * (e.g. "vmdata:vm-101-disk-1") — not a slot — because the slot/unused index
 * changes across detach/re-attach; we always re-scan the VM config to find the
 * disk's current key (scsiN while attached, unusedN while detached).
 *
 * ─── THREE THINGS THIS FILE IS RESPONSIBLE FOR ──────────────────────────────
 *
 * 1. PORTABILITY (a volume is sold as a portable disk, not a welded one).
 *    A Proxmox disk is OWNED by a vmid (`vm-<vmid>-disk-N`), so moving a volume
 *    to another server is not a DB edit — the disk has to be reassigned to the
 *    other VM (`move_disk` + `target-vmid`, which RENAMES the volume). See
 *    `reassignDiskToServer`. PVE requires both VMs on the same node, so a
 *    cross-node move is refused up front instead of half-done.
 *
 * 2. GUEST PREPARATION (format on first use, mount on every use).
 *    Nothing used to format or mount a volume: attach hot-plugged a raw disk and
 *    the notification told the customer to do it themselves. That is also why
 *    `Volume.inUse` was never knowable. `prepareGuestVolume` now does it — and is
 *    written to REFUSE on any ambiguity rather than risk a customer's bytes.
 *
 * 3. SAFE DETACH (never hot-unplug a live filesystem).
 *    A detach used to be an unconditional SCSI unplug with no sync and no
 *    unmount: a volume mounted at /var/lib/mysql lost its device mid-write →
 *    journal abort / InnoDB corruption. `releaseGuestVolume` unmounts first and
 *    REFUSES when the filesystem is still in use, unless the customer has given
 *    an explicit informed override (`payload.ackInUse`).
 *
 * ─── PROXMOX CONFIG WRITES ARE ASYNCHRONOUS ─────────────────────────────────
 * A config POST returns before the config file reflects it, so an immediate GET
 * can hand back the pre-write view. Every read-after-write in this file goes
 * through `waitForConfig` — that race is exactly how volumes ended up with a
 * null `diskName` in production.
 */

async function loadVolume(job: Job) {
  const payload = (job.payload ?? {}) as { volumeId?: string };
  if (!payload.volumeId) throw new Error("volume job: missing volumeId");
  const volume = await db.volume.findUnique({
    where: { id: payload.volumeId },
    // `dedicatedIp` is needed to open an SSH session to the guest (lib/sftp
    // connectionTarget: dedicated IP:22, else PUBLIC_IP:sshPort).
    include: { server: { include: { node: true, dedicatedIp: true } } },
  });
  if (!volume) throw new Error(`Volume ${payload.volumeId} not found`);
  return volume;
}

/** The server a VOLUME_ATTACH should land on. */
async function loadAttachTarget(job: Job, volume: Awaited<ReturnType<typeof loadVolume>>) {
  const payload = (job.payload ?? {}) as { targetServerId?: string };
  // `targetServerId` is authoritative: the enqueueing action deliberately does
  // NOT re-point `Volume.serverId` when a volume moves between servers, because
  // that pin is what stops a reinstall/restore on the server that still
  // physically holds the disk from purging it (worker/index.ts). Fall back to
  // `job.serverId` / `volume.serverId` so jobs queued by the older action (which
  // carried no targetServerId) still resolve correctly.
  const id = payload.targetServerId ?? job.serverId ?? volume.serverId;
  if (!id) return null;
  return db.server.findUnique({
    where: { id },
    include: { node: true, dedicatedIp: true },
  });
}

/** Resolve the Proxmox client + node row for a server (mirrors worker/index.ts). */
async function nodeFor(server: any) {
  const n =
    server?.node ??
    (await db.node.findFirst({ where: { isPrimary: true } })) ??
    (await db.node.findFirst({ where: { enabled: true } }));
  if (!n) {
    return {
      conn: {
        get: pve.get,
        post: pve.post,
        put: pve.put,
        del: pve.del,
        node: envNode,
        waitForTask,
        nextVmid,
        vmStatus,
      } as any,
      row: null,
    };
  }
  return {
    conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }),
    row: n,
  };
}

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[volumes] notify failed", e);
  }
}

/** Strip Proxmox disk options: "vmdata:vm-101-disk-1,size=10G" -> "vmdata:vm-101-disk-1". */
function volidOf(configValue: unknown): string {
  return String(configValue ?? "").split(",")[0].trim();
}

/**
 * True for a real Proxmox disk volid such as "vmdata:vm-102-disk-1" (or a
 * file/dir volid like "vmdata:102/vm-102-disk-1.raw"). Used to reject empty/
 * garbage read-backs so `Volume.diskName` is never persisted as a non-volid.
 */
function isRealVolid(v: unknown): v is string {
  return typeof v === "string" && /^[^,\s:]+:\S*vm-\d+-disk-\d+/.test(v.trim());
}

/** The vmid that OWNS a volid ("vmdata:vm-102-disk-1" -> 102), or null. */
function vmidOfVolid(volid: unknown): number | null {
  const m = /vm-(\d+)-disk-\d+/.exec(String(volid ?? ""));
  if (!m) return null;
  const n = Number(m[1]);
  return Number.isInteger(n) && n > 0 ? n : null;
}

/** All disk volids currently referenced by a VM config (scsi/virtio/ide/sata/unused). */
function diskVolids(config: Record<string, any>): string[] {
  const out: string[] = [];
  for (const [k, v] of Object.entries(config)) {
    if (typeof v !== "string") continue;
    if (!/^(scsi|virtio|ide|sata|unused)\d+$/.test(k)) continue;
    const id = volidOf(v);
    if (isRealVolid(id)) out.push(id);
  }
  return out;
}

/** First free scsiN slot (scsi0 is the OS disk). Proxmox supports scsi0..scsi30. */
function freeScsiSlot(config: Record<string, any>): string {
  for (let i = 1; i <= 30; i++) {
    if (config[`scsi${i}`] === undefined) return `scsi${i}`;
  }
  throw new Error("no free scsi slot available on this VM");
}

/** Find the config key (scsiN / unusedN / …) that currently references `volid`. */
function keyForVolid(config: Record<string, any>, volid: string): string | null {
  for (const [k, v] of Object.entries(config)) {
    if (typeof v === "string" && volidOf(v) === volid) return k;
  }
  return null;
}

/**
 * Read a VM config, polling until `ready(config)` is satisfied.
 *
 * Proxmox applies a config POST ASYNCHRONOUSLY: the call returns before the
 * config file is rewritten, so an immediate GET can still return the pre-write
 * view. Every read-after-write here uses this — the un-polled version is how
 * ATTACHED volumes ended up with `diskName === null`, which then made a
 * re-attach hand back a brand-new empty disk and orphan the real one.
 */
async function waitForConfig(
  conn: any,
  vmid: number,
  ready: (config: Record<string, any>) => boolean,
  tries = 10,
  delayMs = 1000
): Promise<Record<string, any>> {
  let config = (await conn.get(`/nodes/${conn.node}/qemu/${vmid}/config`)) as Record<string, any>;
  for (let i = 0; i < tries && !ready(config); i++) {
    await new Promise((r) => setTimeout(r, delayMs));
    config = (await conn.get(`/nodes/${conn.node}/qemu/${vmid}/config`)) as Record<string, any>;
  }
  return config;
}

// ===========================================================================
// GUEST SIDE — detect / format / mount / unmount
// ===========================================================================
/**
 * Everything below runs inside the customer's VM over SSH, and every command is
 * built the way lib/ssh-exec.ts demands: values are validated against a
 * shell-inert allowlist FIRST (we reject, never sanitize) and quoted second.
 *
 * The formatting decision is the most dangerous operation in this file, so it is
 * deliberately gated by five INDEPENDENT layers, and any one of them failing (or
 * being merely unclear) means we mount nothing and format nothing:
 *
 *   1. IDENTITY — the device must be one that appeared in the guest between a
 *      snapshot taken BEFORE the hot-plug and a poll taken after it, and exactly
 *      one such device may appear. We never guess "probably /dev/sdb".
 *   2. SIZE — that device's size must match the volume's nominal size.
 *   3. HISTORY — the Volume row must never have carried a filesystem
 *      (`fsType`/`mountPath`/`inUse` all unset). If the row says it was
 *      formatted but the disk looks blank, that contradiction means we may be
 *      looking at the wrong device: refuse and report, touch nothing.
 *   4. SIGNATURES — `blkid`, `wipefs -n`, children, holders and mountpoints must
 *      all come back empty, AND three separate 1–4 MiB windows (start, middle,
 *      end) must read as pure zeros. Every filesystem/partition table/LVM/LUKS/
 *      md-raid layout writes a header inside those windows, so "no signature and
 *      zeros at both ends" is as close to proof-of-blank as a disk allows.
 *   5. mke2fs ITSELF — `mkfs.ext4` is invoked with a SINGLE `-F`. That waives
 *      only the "this is a whole device, not a partition" objection; a single
 *      `-F` still makes mke2fs refuse a device that is mounted or otherwise in
 *      use by the kernel (two are required to override that), so the kernel gets
 *      the last veto after all our own checks.
 */

const GiB = 1024 ** 3;
/** A bare kernel block-device name we are willing to interpolate: "sdb", "vdc". */
const DEV_NAME_RE = /^[a-z][a-z0-9]{1,31}$/;
const UUID_RE = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
/** Absolute mount path we either generate or read back from the guest. */
const MOUNT_PATH_RE = /^\/[A-Za-z0-9._/-]{1,120}$/;
/** Filesystems we are willing to mount unattended. */
const MOUNTABLE_FS = new Set(["ext2", "ext3", "ext4", "xfs", "btrfs"]);
/** What a blank volume gets formatted with. */
const VOLUME_FS = "ext4";
/**
 * The mount point the migration engine uses for a volume it adopts as Docker
 * storage (worker/migrate-real.ts EXTRA_DISK_MOUNT). `/var/lib/docker` and
 * `/var/lib/containerd` are BIND-MOUNTED out of it, which is precisely the
 * layout where an unannounced detach pulls the filesystem out from under every
 * running container.
 */
const DOCKER_VOLUME_MOUNT = "/mnt/nxeon-nxeon-data".replace("nxeon-nxeon", "nxeon");

/** Strip control characters and clamp — everything read back from the guest. */
function clean(s: unknown, max: number): string {
  return String(s ?? "")
    .replace(/[\x00-\x1f\x7f]/g, " ")
    .trim()
    .slice(0, max);
}

/**
 * Run one guest command, turning transport failures into an empty result instead
 * of an exception: every caller treats "no output" as "unclear → do not touch",
 * so a timeout can never be mistaken for a green light (nor fail an attach that
 * has already been paid for and hot-plugged).
 */
async function sh(
  conn: Client,
  cmd: string,
  timeoutMs: number = QUICK_TIMEOUT_MS
): Promise<{ code: number | null; stdout: string; stderr: string }> {
  try {
    return await exec(conn, cmd, timeoutMs);
  } catch (e: any) {
    return { code: null, stdout: "", stderr: String(e?.message ?? e) };
  }
}

/** Pull `KEY=value` out of a probe's stdout. */
function kv(out: string, key: string): string {
  return clean(new RegExp(`^${key}=(.*)$`, "m").exec(out ?? "")?.[1] ?? "", 255);
}

type GuestDisk = { name: string; type: string; sizeBytes: number; fstype: string; mount: string; pkname: string };

function parseLsblk(out: string): GuestDisk[] {
  const rows: GuestDisk[] = [];
  for (const line of (out ?? "").split("\n")) {
    if (!line.trim()) continue;
    const map: Record<string, string> = {};
    for (const m of line.matchAll(/([A-Z]+)="([^"]*)"/g)) map[m[1]] = m[2];
    if (!map.NAME) continue;
    rows.push({
      name: clean(map.NAME, 64),
      type: clean(map.TYPE ?? "", 32),
      sizeBytes: Number(map.SIZE) || 0,
      fstype: clean(map.FSTYPE ?? "", 32),
      mount: clean(map.MOUNTPOINT ?? "", 200),
      pkname: clean(map.PKNAME ?? "", 64),
    });
  }
  return rows;
}

/** Every block device the guest can see right now, or null if it could not be read. */
async function guestBlockDevices(conn: Client): Promise<GuestDisk[] | null> {
  const r = await sh(conn, `lsblk -b -P -o NAME,TYPE,SIZE,FSTYPE,MOUNTPOINT,PKNAME 2>/dev/null`);
  const rows = parseLsblk(r.stdout);
  return rows.length ? rows : null;
}

/**
 * Names of the whole disks that carry (or stack under) the root filesystem.
 * Nothing in that tree is ever a candidate, however it is stacked (partition,
 * LVM, dm-crypt) — walking PKNAME keeps an LVM root from ever looking "blank".
 */
async function rootDiskNames(conn: Client, rows: GuestDisk[]): Promise<Set<string>> {
  const byName = new Map(rows.map((r) => [r.name, r]));
  const topOf = (name: string): string => {
    let cur = name;
    for (let i = 0; i < 8; i++) {
      const row = byName.get(cur);
      if (!row?.pkname || row.pkname === cur) break;
      cur = row.pkname;
    }
    return cur;
  };
  const out = new Set<string>();
  const r = await sh(conn, `findmnt -nro SOURCE / 2>/dev/null | head -n1`);
  const src = clean(r.stdout, 128);
  if (src.startsWith("/dev/")) {
    out.add(topOf(src.slice(src.lastIndexOf("/") + 1)));
    const pk = await sh(conn, `lsblk -no PKNAME ${shellQuote(src)} 2>/dev/null | head -n1`);
    const parent = clean(pk.stdout, 64);
    if (parent) out.add(topOf(parent));
  }
  return out;
}

/** Whole-disk names visible in the guest (excluding the root disk's tree). */
async function guestDiskNames(conn: Client): Promise<Set<string> | null> {
  const rows = await guestBlockDevices(conn);
  if (!rows) return null;
  const roots = await rootDiskNames(conn, rows);
  return new Set(rows.filter((d) => d.type === "disk" && !roots.has(d.name)).map((d) => d.name));
}

type DeviceProbe = {
  ok: boolean;
  sizeBytes: number;
  fsType: string;
  ptType: string;
  uuid: string;
  mount: string;
  /** True only when EVERY blankness test came back negative. */
  blank: boolean;
  /** Human-readable list of the signs of data we found (empty when blank). */
  evidence: string[];
};

/**
 * READ-ONLY interrogation of one whole disk, in a single round trip.
 *
 * `blkid -p` probes the device itself rather than the (possibly stale) cache, and
 * the three `dd` windows catch layouts libblkid does not know: a filesystem, a
 * partition table, an LVM PV label, a LUKS header, an md-raid superblock (1.0
 * lives at the END of the device — hence the tail window) or a swap area all put
 * bytes inside them. Reading is the only thing this function does.
 */
async function probeDevice(conn: Client, name: string): Promise<DeviceProbe> {
  const fail: DeviceProbe = { ok: false, sizeBytes: 0, fsType: "", ptType: "", uuid: "", mount: "", blank: false, evidence: ["the disk could not be interrogated"] };
  if (!DEV_NAME_RE.test(name)) return fail;
  const dev = `/dev/${name}`;
  const q = shellQuote(dev);
  const probe = [
    `SZ=$(blockdev --getsize64 ${q} 2>/dev/null || echo 0)`,
    `echo "SIZE=$SZ"`,
    `echo "FSTYPE=$(blkid -p -s TYPE -o value ${q} 2>/dev/null)"`,
    `echo "PTTYPE=$(blkid -p -s PTTYPE -o value ${q} 2>/dev/null)"`,
    `echo "USAGE=$(blkid -p -s USAGE -o value ${q} 2>/dev/null)"`,
    `echo "UUID=$(blkid -s UUID -o value ${q} 2>/dev/null)"`,
    `echo "MOUNT=$(findmnt -nro TARGET -S ${q} 2>/dev/null | head -n1)"`,
    `echo "HOLDERS=$(ls -A /sys/block/${name}/holders 2>/dev/null | tr '\\n' ' ')"`,
    `echo "CHILDREN=$(lsblk -no NAME ${q} 2>/dev/null | tail -n +2 | tr -d ' ' | tr '\\n' ' ')"`,
    `if command -v wipefs >/dev/null 2>&1; then echo "WIPEFS=$(wipefs -n ${q} 2>/dev/null | wc -l)"; else echo "WIPEFS=na"; fi`,
    // Three zero-windows: first 4 MiB, 1 MiB at the midpoint, last 1 MiB.
    `nz() { dd if=${q} bs=1048576 skip="$1" count="$2" iflag=skip_bytes,count_bytes 2>/dev/null | tr -d '\\000' | wc -c; }`,
    `if [ "$SZ" -gt 8388608 ]; then`,
    `  echo "ZHEAD=$(nz 0 4194304)"`,
    `  echo "ZMID=$(nz $((SZ/2)) 1048576)"`,
    `  echo "ZTAIL=$(nz $((SZ-1048576)) 1048576)"`,
    `fi`,
    `echo "PROBE=OK"`,
  ].join("; ");

  const r = await sh(conn, probe, SETUP_TIMEOUT_MS);
  if (kv(r.stdout, "PROBE") !== "OK") return fail;

  const sizeBytes = Number(kv(r.stdout, "SIZE")) || 0;
  const fsType = kv(r.stdout, "FSTYPE").toLowerCase();
  const ptType = kv(r.stdout, "PTTYPE").toLowerCase();
  const usage = kv(r.stdout, "USAGE").toLowerCase();
  const uuid = kv(r.stdout, "UUID");
  const mount = kv(r.stdout, "MOUNT");
  const holders = kv(r.stdout, "HOLDERS");
  const children = kv(r.stdout, "CHILDREN");
  const wipefs = kv(r.stdout, "WIPEFS");
  const zhead = kv(r.stdout, "ZHEAD");
  const zmid = kv(r.stdout, "ZMID");
  const ztail = kv(r.stdout, "ZTAIL");

  const evidence: string[] = [];
  if (fsType) evidence.push(`a ${fsType} filesystem`);
  if (ptType) evidence.push(`a ${ptType} partition table`);
  if (usage && !fsType && !ptType) evidence.push(`a ${usage} signature`);
  if (uuid) evidence.push(`filesystem UUID ${uuid}`);
  if (mount) evidence.push(`it is mounted at ${mount}`);
  if (holders) evidence.push(`kernel holders (${holders})`);
  if (children) evidence.push(`child devices (${children})`);
  // `wipefs -n` prints nothing at all when it finds no magic; any line is a hit.
  if (wipefs !== "na" && Number(wipefs) > 0) evidence.push("on-disk signatures reported by wipefs");
  // A missing/short size, or zero-windows we could not read, is ambiguity — and
  // ambiguity is treated exactly like data.
  if (sizeBytes <= 8 * 1024 * 1024) evidence.push("its size could not be read");
  else if (zhead !== "0" || zmid !== "0" || ztail !== "0") {
    evidence.push(
      zhead === "" || zmid === "" || ztail === ""
        ? "the raw start/middle/end of the disk could not be read back"
        : "non-zero bytes at the start, middle or end of the disk"
    );
  }

  return { ok: true, sizeBytes, fsType, ptType, uuid, mount, blank: evidence.length === 0, evidence };
}

/** Does `sizeBytes` plausibly belong to a `sizeGB` volume? */
function sizeMatches(sizeBytes: number, sizeGB: number): boolean {
  const expected = Math.max(1, Math.round(sizeGB)) * GiB;
  // Storage back-ends round up to an extent / volblocksize, so allow a little
  // slack — but not enough to confuse a volume with a differently-sized disk.
  const slack = Math.max(64 * 1024 * 1024, expected * 0.03);
  return sizeBytes >= expected - slack && sizeBytes <= expected + slack;
}

/** The default, stable mount point for a volume. Stable across re-attaches. */
function defaultMountPath(volumeId: string): string | null {
  const slug = String(volumeId ?? "").toLowerCase().replace(/[^a-z0-9]/g, "");
  if (slug.length < 8) return null;
  const path = `/mnt/nxeon-vol-${slug}`;
  return MOUNT_PATH_RE.test(path) ? path : null;
}

/**
 * Give the guest a chance to notice a freshly hot-plugged SCSI disk, then return
 * the ONE device that appeared since `before`.
 *
 * Identity by set-difference (not by name, size or slot arithmetic) is what makes
 * the rest of this safe: the device we go on to touch is, by construction, the one
 * that appeared when we plugged this volume in. Zero or several new devices means
 * we cannot say which disk is the customer's — so we say so and stop.
 */
async function findAttachedDevice(
  conn: Client,
  before: Set<string>,
  sizeGB: number
): Promise<{ name: string } | { error: string }> {
  // Writing "- - -" to a SCSI host's scan node only asks the kernel to re-probe.
  await sh(conn, `for h in /sys/class/scsi_host/host*/scan; do echo '- - -' > "$h" 2>/dev/null; done; udevadm settle 2>/dev/null; true`);

  let appeared: GuestDisk[] = [];
  for (let i = 0; i < 12; i++) {
    const rows = await guestBlockDevices(conn);
    if (rows) {
      const roots = await rootDiskNames(conn, rows);
      appeared = rows.filter((d) => d.type === "disk" && !roots.has(d.name) && !before.has(d.name));
      if (appeared.length) break;
    }
    await new Promise((r) => setTimeout(r, 2500));
  }

  if (appeared.length === 0) {
    return { error: "the server did not report a new disk after the attach (a reboot usually makes it appear)" };
  }
  if (appeared.length > 1) {
    return { error: `${appeared.length} new disks appeared at once, so we cannot tell which one is this volume` };
  }
  const dev = appeared[0];
  if (!DEV_NAME_RE.test(dev.name)) {
    return { error: `the new disk has an unexpected device name (${dev.name.slice(0, 20)})` };
  }
  if (!sizeMatches(dev.sizeBytes, sizeGB)) {
    return {
      error:
        `the new disk is ${Math.round(dev.sizeBytes / GiB)} GB but this volume is ${sizeGB} GB — ` +
        `refusing to touch a disk we cannot positively identify`,
    };
  }
  return { name: dev.name };
}

/**
 * Persist an ALREADY-FORMATTED filesystem: an /etc/fstab entry BY UUID (never by
 * /dev/sdX — a volume can come back as a different letter, and then fstab mounts
 * the wrong disk) with `nofail`, then mount it.
 *
 * `nofail` is not optional. A volume can be detached, moved to another server or
 * simply fail to appear; without `nofail` systemd holds local-fs.target and the
 * customer's server does not finish booting. An unmounted disk is a support
 * ticket, a server that will not boot is an outage.
 *
 * Idempotent: the grep guard and the `mountpoint -q` short-circuit make a re-run
 * a no-op. NEVER formats — that decision belongs to the caller alone.
 */
async function mountVolumeFs(
  conn: Client,
  devName: string,
  mountPath: string,
  fsType: string
): Promise<{ ok: true; uuid: string } | { ok: false; error: string }> {
  if (!DEV_NAME_RE.test(devName)) return { ok: false, error: "device name failed validation" };
  if (!MOUNT_PATH_RE.test(mountPath) || mountPath.includes("..") || mountPath.includes("//")) {
    return { ok: false, error: `unsupported mount path ${mountPath.slice(0, 40)}` };
  }
  if (!MOUNTABLE_FS.has(fsType)) return { ok: false, error: `unsupported filesystem ${fsType.slice(0, 20)}` };

  const dev = shellQuote(`/dev/${devName}`);
  const path = shellQuote(mountPath);

  // udev may still be settling right after a mkfs; give the UUID two chances.
  let uuid = "";
  for (let i = 0; i < 2 && !UUID_RE.test(uuid); i++) {
    if (i) await sh(conn, `udevadm settle 2>/dev/null; true`);
    uuid = clean((await sh(conn, `blkid -s UUID -o value ${dev} 2>/dev/null`)).stdout, 64);
  }
  if (!UUID_RE.test(uuid)) return { ok: false, error: "could not read a filesystem UUID back" };

  // Refuse to stack our mount on top of somebody else's filesystem.
  const occupied = await sh(conn, `findmnt -nro SOURCE --mountpoint ${path} 2>/dev/null | head -n1`);
  const occupiedBy = clean(occupied.stdout, 128);
  if (occupiedBy && occupiedBy !== `/dev/${devName}`) {
    return { ok: false, error: `${mountPath} is already in use by ${occupiedBy}` };
  }

  await sh(conn, `mkdir -p ${path}`);
  await sh(
    conn,
    `grep -q "UUID=${uuid} " /etc/fstab || printf 'UUID=%s %s %s defaults,nofail 0 2\\n' '${uuid}' ${path} ${shellQuote(fsType)} >> /etc/fstab`
  );
  await sh(conn, `mountpoint -q ${path} || mount ${path} 2>&1 || mount ${dev} ${path} 2>&1`, SETUP_TIMEOUT_MS);
  const live = await sh(conn, `mountpoint -q ${path} && echo MOUNTED`);
  if (!clean(live.stdout, 32).includes("MOUNTED")) {
    return { ok: false, error: `mounting ${mountPath} failed` };
  }
  return { ok: true, uuid };
}

/** Where should this volume be mounted? Never invents a path over an existing layout. */
async function resolveMountPath(
  conn: Client,
  volume: { id: string; mountPath: string | null },
  uuid: string
): Promise<string | null> {
  // 1) An fstab entry for THIS filesystem wins: it is where the guest already
  //    expects the disk, and the migration engine bind-mounts Docker's stores out
  //    of that directory. Mounting somewhere else would leave those binds dangling.
  if (UUID_RE.test(uuid)) {
    const r = await sh(conn, `awk -v u="UUID=${uuid}" '$1==u {print $2; exit}' /etc/fstab 2>/dev/null`);
    const fromFstab = clean(r.stdout, 200);
    if (MOUNT_PATH_RE.test(fromFstab)) return fromFstab;
  }
  // 2) Then the path we recorded last time (kept across a detach for the same reason).
  if (volume.mountPath && MOUNT_PATH_RE.test(volume.mountPath)) return volume.mountPath;
  // 3) Otherwise our own stable path.
  return defaultMountPath(volume.id);
}

type PrepareResult =
  | { prepared: true; fsType: string; mountPath: string; detail: string }
  | { prepared: false; detail: string; fsType?: string };

/**
 * Make an attached volume usable: format it if (and ONLY if) it is provably
 * blank, mount it either way, and record enough to make a later detach safe.
 *
 * `formatAllowed` is the DB-side half of the format gate: the Volume row must
 * never have carried a filesystem. It is deliberately separate from the
 * disk-side evidence so that the two have to agree.
 */
async function prepareGuestVolume(
  server: any,
  volume: { id: string; sizeGB: number; mountPath: string | null; fsType: string | null; inUse: boolean },
  before: Set<string>
): Promise<PrepareResult> {
  const formatAllowed = !volume.fsType && !volume.mountPath && !volume.inUse;
  try {
    return await withServerSsh(server, async (conn) => {
      const found = await findAttachedDevice(conn, before, volume.sizeGB);
      if ("error" in found) return { prepared: false, detail: found.error };

      const probe = await probeDevice(conn, found.name);
      if (!probe.ok) {
        return { prepared: false, detail: `/dev/${found.name} could not be interrogated, so it was left untouched` };
      }

      // ── Already mounted: adopt it, change nothing about the data. ──────────
      if (probe.mount) {
        const fsType = probe.fsType || "unknown";
        if (!MOUNT_PATH_RE.test(probe.mount)) {
          return { prepared: false, detail: `it is already mounted at an unsupported path (${probe.mount.slice(0, 40)})`, fsType: probe.fsType || undefined };
        }
        // Make sure that mount survives a reboot, without touching the contents.
        if (MOUNTABLE_FS.has(fsType) && UUID_RE.test(probe.uuid)) {
          await sh(
            conn,
            `grep -q "UUID=${probe.uuid} " /etc/fstab || printf 'UUID=%s %s %s defaults,nofail 0 2\\n' '${probe.uuid}' ${shellQuote(probe.mount)} ${shellQuote(fsType)} >> /etc/fstab`
          );
        }
        return {
          prepared: true,
          fsType,
          mountPath: probe.mount,
          detail: `already mounted at ${probe.mount} (${fsType}) — its contents were not touched`,
        };
      }

      // ── Carries data: mount a filesystem we understand, never reformat. ────
      if (probe.fsType || probe.ptType) {
        if (probe.ptType || !MOUNTABLE_FS.has(probe.fsType)) {
          // A partition table (or an fs we do not mount unattended) means the
          // layout is the customer's business; guessing which partition to mount
          // is how you mount the wrong thing.
          return {
            prepared: false,
            fsType: probe.fsType || probe.ptType,
            detail:
              `/dev/${found.name} already contains ${probe.evidence[0] ?? "existing data"}. ` +
              `It was attached but NOT formatted or mounted — mount it yourself so nothing is guessed.`,
          };
        }
        const path = await resolveMountPath(conn, volume, probe.uuid);
        if (!path) return { prepared: false, fsType: probe.fsType, detail: "could not derive a mount point" };
        const m = await mountVolumeFs(conn, found.name, path, probe.fsType);
        if (!m.ok) return { prepared: false, fsType: probe.fsType, detail: m.error };
        return {
          prepared: true,
          fsType: probe.fsType,
          mountPath: path,
          detail: `existing ${probe.fsType} filesystem mounted at ${path} — nothing was reformatted`,
        };
      }

      // ── Nothing detected on the disk. Format ONLY if history agrees. ───────
      if (!formatAllowed) {
        // The row says this volume carries a filesystem but the disk shows no
        // trace of one. That is a contradiction, and the likeliest explanations
        // (wrong device, a disk that was recreated empty) both end with somebody
        // formatting data. Stop and hand it to a human.
        return {
          prepared: false,
          detail:
            `refusing to touch /dev/${found.name}: this volume is recorded as ${volume.fsType ?? "formatted"}` +
            `${volume.mountPath ? ` mounted at ${volume.mountPath}` : ""}, but the disk reports no filesystem at all. ` +
            `Nothing was formatted or mounted — please contact support before writing to it.`,
        };
      }
      if (!probe.blank) {
        return {
          prepared: false,
          detail: `refusing to format /dev/${found.name}: ${probe.evidence.join("; ")}`,
        };
      }

      // Single `-F`: waives only the "whole device, not a partition" objection.
      // mke2fs still refuses a device it believes is mounted or in use, which is
      // the last independent veto after our own five checks.
      const mk = await sh(
        conn,
        `mkfs.${VOLUME_FS} -F -m 0 -L nxeon-vol ${shellQuote(`/dev/${found.name}`)} 2>&1`,
        INSTALL_TIMEOUT_MS
      );
      if (mk.code !== 0) {
        return { prepared: false, detail: `mkfs.${VOLUME_FS} refused /dev/${found.name}: ${clean(mk.stdout || mk.stderr, 200)}` };
      }
      const path = (await resolveMountPath(conn, volume, "")) ?? defaultMountPath(volume.id);
      if (!path) return { prepared: false, detail: "could not derive a mount point" };
      const m = await mountVolumeFs(conn, found.name, path, VOLUME_FS);
      if (!m.ok) return { prepared: false, fsType: VOLUME_FS, detail: m.error };
      return {
        prepared: true,
        fsType: VOLUME_FS,
        mountPath: path,
        detail: `formatted ${VOLUME_FS} and mounted at ${path} (fstab UUID entry with nofail)`,
      };
    });
  } catch (e: any) {
    return { prepared: false, detail: `the server could not be reached to prepare the disk (${clean(e?.message ?? e, 120)})` };
  }
}

/** What the customer can run by hand when we deliberately did not prepare the disk. */
function manualPrepareHint(volumeId: string): string {
  const path = defaultMountPath(volumeId) ?? "/mnt/data";
  return (
    `lsblk   # find the new disk, e.g. /dev/sdb\n` +
    `mkfs.ext4 /dev/sdb && mkdir -p ${path} && mount /dev/sdb ${path}\n` +
    `echo "UUID=$(blkid -s UUID -o value /dev/sdb) ${path} ext4 defaults,nofail 0 2" >> /etc/fstab`
  );
}

type ReleaseResult =
  /** The filesystem is not (or no longer) mounted — the disk can be unplugged. */
  | { released: true; detail: string }
  /** Something still depends on it. Refuse unless the customer overrode it. */
  | { released: false; dependents: string[]; detail: string };

/**
 * Take the volume's filesystem out of service BEFORE the disk is unplugged.
 *
 * The old detach was a bare SCSI unplug: no sync, no unmount, no guest-agent
 * involvement. A volume mounted at /var/lib/mysql simply lost its device mid
 * write — journal abort, InnoDB corruption — while the UI promised "Data is
 * preserved.". And the same primitive fires with no human present from billing
 * (worker/product-renewals.ts queues VOLUME_DETACH on an overdue volume attached
 * to a RUNNING VM), which is why the refusal lives here and not only in the UI.
 *
 * Nothing is mutated before the decision: `sync` and the probes are harmless, the
 * fstab edit happens only once we know the unmount is going ahead. If the worker
 * dies between the unmount and the fstab edit the entry is stale — which is
 * survivable only because every entry we write carries `nofail`.
 */
async function releaseGuestVolume(
  server: any,
  volume: { id: string; sizeGB: number; mountPath: string | null; fsType: string | null; inUse: boolean },
  ackInUse: boolean
): Promise<ReleaseResult> {
  const knownFs = !!(volume.inUse || volume.mountPath || volume.fsType);
  try {
    return await withServerSsh(server, async (conn) => {
      // Which device is ours? The recorded mount point is the reliable link (it
      // is unique to this volume); otherwise fall back to a size match, and treat
      // "several disks could be it" as in-use rather than guessing.
      let devName = "";
      let mountPath = "";
      if (volume.mountPath && MOUNT_PATH_RE.test(volume.mountPath)) {
        const r = await sh(conn, `findmnt -nro SOURCE --mountpoint ${shellQuote(volume.mountPath)} 2>/dev/null | head -n1`);
        const src = clean(r.stdout, 128);
        if (src.startsWith("/dev/")) {
          devName = src.slice(5);
          mountPath = volume.mountPath;
        }
      }
      if (!devName) {
        const rows = await guestBlockDevices(conn);
        if (!rows) {
          return knownFs
            ? { released: false, dependents: [], detail: "the server's disks could not be listed, so we cannot confirm the filesystem is idle" }
            : { released: true, detail: "no filesystem is recorded for this volume and the guest could not be probed" };
        }
        const roots = await rootDiskNames(conn, rows);
        const candidates = rows.filter(
          (d) => d.type === "disk" && !roots.has(d.name) && sizeMatches(d.sizeBytes, volume.sizeGB)
        );
        const mounted = candidates.filter((d) => d.mount || rows.some((o) => o.pkname === d.name && o.mount));
        if (mounted.length === 0) {
          return { released: true, detail: "the volume's filesystem is not mounted" };
        }
        if (mounted.length > 1) {
          return {
            released: false,
            dependents: mounted.map((d) => `/dev/${d.name} mounted at ${d.mount || "a partition mount point"}`),
            detail: `${mounted.length} mounted disks match this volume's size, so we cannot tell which one to unmount`,
          };
        }
        devName = mounted[0].name;
        mountPath = mounted[0].mount;
      }
      if (!DEV_NAME_RE.test(devName) || !MOUNT_PATH_RE.test(mountPath)) {
        return { released: true, detail: "the volume's filesystem is not mounted" };
      }

      const path = shellQuote(mountPath);
      const uuid = clean((await sh(conn, `blkid -s UUID -o value ${shellQuote(`/dev/${devName}`)} 2>/dev/null`)).stdout, 64);

      // Flush before anything else — cheap, and the one thing the old code never did.
      await sh(conn, `sync`, SETUP_TIMEOUT_MS);

      const plain = await sh(conn, `umount ${path} 2>&1`, SETUP_TIMEOUT_MS);
      const stillMounted = clean((await sh(conn, `mountpoint -q ${path} && echo BUSY`)).stdout, 32).includes("BUSY");

      if (stillMounted) {
        const dependents = await mountDependents(conn, mountPath);
        if (!ackInUse) {
          return {
            released: false,
            dependents,
            detail: `${mountPath} could not be unmounted: ${clean(plain.stdout || plain.stderr, 160) || "the filesystem is in use"}`,
          };
        }
        // Informed override: the customer accepted that whatever is using this
        // filesystem will break. A lazy unmount detaches the tree now and lets
        // the kernel release it when the last reference goes, which is still far
        // better than yanking the device out from under an open file.
        await removeFstabEntry(conn, uuid);
        await sh(conn, `umount -l ${path} 2>&1`, SETUP_TIMEOUT_MS);
        await sh(conn, `sync`, SETUP_TIMEOUT_MS);
        return {
          released: true,
          detail: `${mountPath} was still in use (${dependents.join(", ") || "unknown holders"}) and was force-unmounted on your instruction`,
        };
      }

      await removeFstabEntry(conn, uuid);
      return { released: true, detail: `${mountPath} was unmounted cleanly` };
    });
  } catch (e: any) {
    // Cannot reach the guest. If we know it carries a mounted filesystem we
    // refuse: an unverified hot-unplug is exactly the corruption we are here to
    // prevent. If no filesystem was ever recorded there is nothing to corrupt.
    const why = clean(e?.message ?? e, 120);
    return knownFs
      ? { released: false, dependents: [], detail: `the server could not be reached to unmount the volume first (${why})` }
      : { released: true, detail: `no filesystem is recorded for this volume and the server is unreachable (${why})` };
  }
}

/**
 * Drop the fstab line we own (matched on the filesystem UUID, so nothing else can
 * match it). Deliberately leaves any bind-mount lines the migration engine wrote
 * alone: those are its configuration, not ours, and every entry it writes also
 * carries `nofail`, so a missing source directory cannot break the boot.
 */
async function removeFstabEntry(conn: Client, uuid: string): Promise<void> {
  if (!UUID_RE.test(uuid)) return;
  await sh(conn, `sed -i "\\|^UUID=${uuid}[[:space:]]|d" /etc/fstab 2>/dev/null; true`);
}

/** Name what is holding a mount point open, for an honest refusal message. */
async function mountDependents(conn: Client, mountPath: string): Promise<string[]> {
  if (!MOUNT_PATH_RE.test(mountPath)) return [];
  const q = shellQuote(mountPath);
  const r = await sh(
    conn,
    // Bind mounts sourced from inside this filesystem (how Docker's stores are
    // relocated onto a volume), then the processes with files open under it.
    `findmnt -rno TARGET,SOURCE 2>/dev/null | awk -v p=${q} '{ if (index($2, p"/")==1 || index($1, p"/")==1) print "bind " $1 }' | sort -u | head -n 8; ` +
      `P=$(fuser -Mm ${q} 2>/dev/null | tr -cd '0-9 \\n'); ` +
      `[ -n "$P" ] && ps -o comm= -p $P 2>/dev/null | sort -u | head -n 8 | sed 's/^/proc /'; true`
  );
  const out: string[] = [];
  for (const line of clean(r.stdout, 2000).split("\n")) {
    const t = line.trim();
    if (t.startsWith("bind ")) out.push(`${t.slice(5)} (bind-mounted out of this volume)`);
    else if (t.startsWith("proc ")) out.push(`${t.slice(5)} (running process)`);
  }
  return out.slice(0, 10);
}

// ===========================================================================
// JOB HANDLERS
// ===========================================================================

/**
 * VOLUME_CREATE — logical registration only. No physical disk is created until
 * the volume is first attached (a Proxmox disk must live on a VM). Flip the row
 * from PENDING to DETACHED so the customer can attach it.
 */
export async function volumeCreate(job: Job): Promise<void> {
  const volume = await loadVolume(job);
  if (volume.status === "PENDING") {
    await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
  }
  await notify(
    volume.userId,
    `Volume "${volume.name}" is ready`,
    `${volume.sizeGB} GB block storage is available to attach to a server.`,
    "/dashboard/volumes"
  );
}

/**
 * Move an existing disk from the VM that currently owns it to `target`.
 *
 * A Proxmox disk is named after its owner (`vm-<vmid>-disk-N`), so "the same
 * volume on a different server" is a reassignment, not a config copy:
 * POST .../move_disk with `target-vmid` renames the volume on the storage and
 * moves the config entry across in one locked operation. PVE refuses to do it
 * across nodes, so the caller checks that first.
 *
 * Returns the slot it landed in and its NEW volid — the old `Volume.diskName` is
 * dead the moment the rename succeeds.
 */
async function reassignDiskToServer(
  conn: any,
  volume: { diskName: string | null; name: string },
  sourceVmid: number,
  sourceRunning: boolean,
  target: { vmid: number; hostname: string }
): Promise<{ slot: string; volid: string }> {
  const volid = String(volume.diskName);
  let sourceConfig = (await conn.get(`/nodes/${conn.node}/qemu/${sourceVmid}/config`)) as Record<string, any>;
  let key = keyForVolid(sourceConfig, volid);
  if (!key) {
    // The disk is not on the VM that is supposed to own it. Creating a fresh one
    // would silently hand the customer an empty disk and orphan the real data,
    // so stop instead.
    throw new Error(
      `volume "${volume.name}" is recorded as ${volid} on VM ${sourceVmid}, but that disk is not in the VM's config. ` +
        `Refusing to guess — nothing was changed.`
    );
  }
  if (key.startsWith("scsi")) {
    // The DB says detached but the disk is still plugged in (a detach that never
    // finished). Unplugging a live disk from a RUNNING VM is the corruption we
    // refuse elsewhere, so refuse it here too.
    if (sourceRunning) {
      throw new Error(
        `volume "${volume.name}" is still plugged into VM ${sourceVmid} as ${key}. Detach it from that server first.`
      );
    }
    await conn.post(`/nodes/${conn.node}/qemu/${sourceVmid}/config`, { delete: key });
    sourceConfig = await waitForConfig(conn, sourceVmid, (c) => {
      const k = keyForVolid(c, volid);
      return !!k && k.startsWith("unused");
    });
    key = keyForVolid(sourceConfig, volid);
    if (!key || key.startsWith("scsi")) {
      throw new Error(`could not detach ${volid} from VM ${sourceVmid} before moving it`);
    }
  }

  const targetConfig = (await conn.get(`/nodes/${conn.node}/qemu/${target.vmid}/config`)) as Record<string, any>;
  const slot = freeScsiSlot(targetConfig);

  const upid = await conn.post(`/nodes/${conn.node}/qemu/${sourceVmid}/move_disk`, {
    disk: key,
    "target-vmid": target.vmid,
    "target-disk": slot,
  });
  if (typeof upid === "string" && upid.startsWith("UPID")) await conn.waitForTask(upid);

  // The volume was RENAMED to vm-<target>-disk-N, so read the new volid back —
  // polling, because the config write lands after the API call returns.
  const after = await waitForConfig(conn, target.vmid, (c) => isRealVolid(volidOf(c[slot])));
  const newVolid = volidOf(after[slot]);
  if (!isRealVolid(newVolid)) {
    throw new Error(
      `the disk move to ${target.hostname} did not show up in the VM config; not recording a guess. ` +
        `Check VM ${target.vmid} on the hypervisor before retrying.`
    );
  }
  return { slot, volid: newVolid };
}

/**
 * VOLUME_ATTACH — attach the volume to the target server's VM at a free scsi
 * slot, then make it actually usable inside the guest.
 *
 * Three cases:
 *   • first attach            → Proxmox creates "<storage>:<sizeGB>"
 *   • re-attach, same server  → re-use the existing volid, data preserved
 *   • attach to another server → reassign the disk to that VM (data moves with it)
 */
export async function volumeAttach(job: Job): Promise<void> {
  const volume = await loadVolume(job);
  const payload = (job.payload ?? {}) as { ackInUse?: boolean };
  const target = await loadAttachTarget(job, volume);

  if (SANDBOX) {
    // Simulate the whole thing — no Proxmox call, no SSH — but do record the
    // filesystem facts so safe-detach can be exercised in staging.
    await db.volume.update({
      where: { id: volume.id },
      data: {
        status: "ATTACHED",
        serverId: target?.id ?? volume.serverId ?? null,
        diskName: volume.diskName ?? `sandbox:vol-${volume.id}`,
        fsType: volume.fsType ?? VOLUME_FS,
        mountPath: volume.mountPath ?? defaultMountPath(volume.id),
        inUse: true,
      },
    });
    await notify(
      volume.userId,
      `Volume "${volume.name}" attached${target ? ` to ${target.hostname}` : ""}`,
      `${volume.sizeGB} GB is mounted at ${volume.mountPath ?? defaultMountPath(volume.id)} (sandbox — no real disk was touched).`,
      target ? `/dashboard/servers/${target.id}` : "/dashboard/volumes"
    );
    return;
  }
  if (!target || !target.vmid) throw new Error("volume attach: server has no VM");

  const { conn, row } = await nodeFor(target);
  const storage = row?.storageNvme ?? "vmdata";

  // Snapshot the guest's disks BEFORE the hot-plug: the set difference afterwards
  // is the only trustworthy way to know which /dev/sdX is this volume, and it is
  // what stands between a format and somebody else's data.
  let guestBefore: Set<string> | null = null;
  if (target.status === "RUNNING") {
    try {
      guestBefore = await withServerSsh(target, (c) => guestDiskNames(c));
    } catch {
      guestBefore = null; // unreachable guest: attach anyway, prepare nothing
    }
  }

  const hadDisk = isRealVolid(volume.diskName);
  const sourceVmid = hadDisk ? vmidOfVolid(volume.diskName) : null;
  let slot: string;
  let volid: string | null = null;

  if (sourceVmid && sourceVmid !== target.vmid) {
    // ── Portability: the disk lives on another VM; move it. ────────────────
    const sourceServer = volume.serverId
      ? await db.server.findUnique({ where: { id: volume.serverId }, include: { node: true } })
      : await db.server.findFirst({ where: { vmid: sourceVmid }, include: { node: true } });
    const sourceNode = (await nodeFor(sourceServer)).row?.pveNode ?? envNode;
    if (sourceNode !== conn.node) {
      throw new Error(
        `volume "${volume.name}" holds data on Proxmox node ${sourceNode} and ${target.hostname} is on ${conn.node}. ` +
          `Moving a disk between nodes is not supported — attach it to a server on ${sourceNode}.`
      );
    }
    const moved = await reassignDiskToServer(
      conn,
      volume,
      sourceVmid,
      (sourceServer?.status ?? "RUNNING") === "RUNNING",
      { vmid: target.vmid, hostname: target.hostname }
    );
    slot = moved.slot;
    volid = moved.volid;
  } else {
    // ── First attach, or a re-attach to the same server. ───────────────────
    const config = (await conn.get(`/nodes/${conn.node}/qemu/${target.vmid}/config`)) as Record<string, any>;
    slot = freeScsiSlot(config);
    // Snapshot the disks the VM already owns so we can identify a freshly-created
    // one by diff if the slot read-back is unusable (see fallback below).
    const before = new Set(diskVolids(config));

    // A volume that has ever carried a filesystem MUST NOT be re-created from
    // scratch: that hands back an empty disk and orphans the customer's data with
    // no DB reference left pointing at it.
    if (!hadDisk && (volume.fsType || volume.mountPath || volume.inUse)) {
      throw new Error(
        `volume "${volume.name}" is recorded as ${volume.fsType ?? "formatted"} but has no disk id on record. ` +
          `Refusing to create a new empty disk — the existing one must be found first.`
      );
    }

    // Re-use the existing disk (by volid) if this volume was attached before;
    // otherwise let Proxmox create a fresh <storage>:<sizeGB> disk.
    const source = volume.diskName ? volume.diskName : `${storage}:${volume.sizeGB}`;
    await conn.post(`/nodes/${conn.node}/qemu/${target.vmid}/config`, { [slot]: source });

    // Record the STABLE volid (vmdata:vm-<vmid>-disk-N) so detach/re-attach and the
    // reinstall data-safety guard can find this disk later. This MUST NOT be left
    // null: derive it with layered fallbacks rather than trusting a single read.
    const after = await waitForConfig(conn, target.vmid, (c) => isRealVolid(volidOf(c[slot])));
    // 1) Preferred: the volid Proxmox kept/created at the slot we just wrote.
    const atSlot = volidOf(after[slot]);
    if (isRealVolid(atSlot)) {
      volid = atSlot;
    } else if (volume.diskName && isRealVolid(volume.diskName)) {
      // 2) Re-attach path: the disk we asked to attach is a known-good volid.
      volid = volume.diskName;
    } else {
      // 3) First-attach path where the slot read-back didn't yield a volid (pending
      //    config view, momentary omission, …): identify the disk that newly appeared.
      const appeared = diskVolids(after).filter((v) => !before.has(v));
      if (appeared.length === 1) volid = appeared[0];
    }
  }

  // ── Guest side: format (only if provably blank) and mount. ───────────────
  let prep: PrepareResult | null = null;
  if (guestBefore) {
    prep = await prepareGuestVolume(target, volume, guestBefore);
  } else if (target.status === "RUNNING") {
    prep = { prepared: false, detail: "the server could not be reached over SSH, so the disk was not formatted or mounted" };
  } else {
    prep = { prepared: false, detail: "the server is not running, so the disk could not be mounted yet" };
  }

  await db.volume.update({
    where: { id: volume.id },
    data: {
      status: "ATTACHED",
      serverId: target.id,
      // Never regress a previously-recorded good volid to null on a retry.
      diskName: volid ?? volume.diskName ?? null,
      // Only claim a filesystem/mount when we actually established one; never
      // wipe a known fsType because one attempt could not reach the guest.
      fsType: prep.prepared ? prep.fsType : prep.fsType ?? volume.fsType,
      mountPath: prep.prepared ? prep.mountPath : volume.mountPath,
      inUse: prep.prepared,
    },
  });

  if (prep.prepared) {
    await notify(
      volume.userId,
      `Volume "${volume.name}" is mounted on ${target.hostname}`,
      `${volume.sizeGB} GB attached as ${slot} — ${prep.detail}. Detaching it will unmount it first, and while it is assigned to ${target.hostname} that server cannot be reinstalled or restored from a backup.`,
      `/dashboard/servers/${target.id}`
    );
  } else {
    await notify(
      volume.userId,
      `Volume "${volume.name}" attached to ${target.hostname} — not mounted`,
      `${volume.sizeGB} GB is attached as ${slot}, but ${prep.detail}. No data was written to the disk. To finish by hand:\n${manualPrepareHint(volume.id)}`,
      `/dashboard/servers/${target.id}`
    );
  }
  void payload;
}

/**
 * VOLUME_DETACH — unmount the filesystem, then unplug the disk from the VM
 * (Proxmox moves it to an "unused" entry, preserving the data).
 *
 * ─── WHY THE VOLUME STAYS PINNED TO THE SERVER ──────────────────────────────
 * `Volume.serverId` is NOT cleared while a real disk is still owned by that vmid.
 * A detached disk lives on as an `unusedN` entry belonging to `vm-<vmid>-disk-N`,
 * and PVE's `destroy_vm` frees those too (`include_unused => 1`), so a reinstall
 * or a `qmrestore --force` on that vmid destroys it. The reinstall/restore guards
 * in lib/actions.ts, worker/index.ts, lib/actions-server-ops.ts and
 * worker/restore.ts count volumes by `serverId` ALONE for exactly that reason —
 * clearing the pin here would blind them and reopen the "detach, then reinstall,
 * data gone" path.
 *
 * The pin IS cleared when nothing physical is left behind (no disk was ever
 * created), and it is MOVED to the new server by VOLUME_ATTACH once the disk has
 * really been reassigned — which is how a volume becomes portable without ever
 * leaving a real disk unguarded.
 */
export async function volumeDetach(job: Job): Promise<void> {
  const volume = await loadVolume(job);
  const server = volume.server;
  const payload = (job.payload ?? {}) as { ackInUse?: boolean };
  const ackInUse = payload.ackInUse === true;
  // Nothing physical to protect ⇒ safe to unpin. A real disk keeps its pin.
  const keepsDisk = isRealVolid(volume.diskName);

  if (SANDBOX) {
    await db.volume.update({
      where: { id: volume.id },
      data: { status: "DETACHED", inUse: false, serverId: keepsDisk ? volume.serverId : null },
    });
    if (server) {
      await notify(
        volume.userId,
        `Volume "${volume.name}" detached from ${server.hostname}`,
        "The volume and its data are preserved and can be re-attached (sandbox).",
        "/dashboard/volumes"
      );
    }
    return;
  }

  // ── 1. Take the filesystem out of service first. ─────────────────────────
  let releaseDetail = "no filesystem was mounted";
  if (server?.vmid && server.status === "RUNNING") {
    const release = await releaseGuestVolume(server, volume, ackInUse);
    if (!release.released) {
      // Refuse. The disk stays plugged in and the row goes back to ATTACHED —
      // billing's detach sweep flips the status BEFORE the job runs, and leaving
      // it claiming DETACHED while a mounted disk is still bolted on is the kind
      // of lie that produced this whole class of bug.
      await db.volume.update({ where: { id: volume.id }, data: { status: "ATTACHED", inUse: true } });
      const what = release.dependents.length
        ? ` Still in use by: ${release.dependents.join(", ")}.`
        : "";
      await notify(
        volume.userId,
        `Volume "${volume.name}" could NOT be detached safely`,
        `${release.detail}.${what} Nothing was unplugged — your data is untouched. Stop what is using ${volume.mountPath ?? "the volume"} and try again, or confirm the forced detach in the dashboard.`,
        "/dashboard/volumes"
      );
      throw new Error(
        `refusing to unplug volume ${volume.id} from ${server.hostname}: ${release.detail}` +
          (release.dependents.length ? ` (in use by ${release.dependents.join(", ")})` : "")
      );
    }
    releaseDetail = release.detail;
  } else if (server?.vmid && volume.inUse && !ackInUse) {
    // A stopped VM cannot corrupt anything (no live writers), so this is only a
    // notice, not a refusal — recorded so the copy stays honest.
    releaseDetail = "the server is not running, so the filesystem was already offline";
  }

  // ── 2. Now the config change is safe. ────────────────────────────────────
  if (server?.vmid && volume.diskName) {
    const { conn } = await nodeFor(server);
    const config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
    const key = keyForVolid(config, volume.diskName);
    if (key && key.startsWith("scsi")) {
      await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
      // Confirm Proxmox really moved it to an unused entry before we report it.
      await waitForConfig(conn, server.vmid, (c) => {
        const k = keyForVolid(c, String(volume.diskName));
        return !k || !k.startsWith("scsi");
      });
    }
  }

  await db.volume.update({
    where: { id: volume.id },
    data: {
      status: "DETACHED",
      // Not mounted any more. `mountPath`/`fsType` are KEPT on purpose: they are
      // where the guest expects this filesystem (the migration engine bind-mounts
      // Docker's stores out of that directory) and the record that the disk must
      // never be formatted again.
      inUse: false,
      serverId: keepsDisk ? volume.serverId : null,
    },
  });

  if (server) {
    await notify(
      volume.userId,
      `Volume "${volume.name}" detached from ${server.hostname}`,
      keepsDisk
        ? `${releaseDetail}. The data is intact on the disk, which stays assigned to ${server.hostname} — so ${server.hostname} cannot be reinstalled or restored from a backup until you attach this volume to another server or delete it. Billing continues.`
        : `${releaseDetail}. The volume is available to attach to any of your servers.`,
      "/dashboard/volumes"
    );
  }
}

/**
 * VOLUME_DELETE — detach (if attached) then permanently destroy the underlying
 * disk, and remove the Volume row.
 */
export async function volumeDelete(job: Job): Promise<void> {
  const volume = await loadVolume(job);
  const server = volume.server;

  if (SANDBOX) {
    await db.volume.delete({ where: { id: volume.id } });
    await notify(volume.userId, `Volume "${volume.name}" deleted`, undefined, "/dashboard/volumes");
    return;
  }

  // The customer has accepted losing this volume's data, so a busy filesystem is
  // NOT a reason to refuse here — but unmounting first still matters: yanking the
  // device from under an open file wedges the processes using it and can take
  // unrelated services on the same server down with it. Best effort only.
  if (server?.vmid && server.status === "RUNNING" && (volume.inUse || volume.mountPath)) {
    await releaseGuestVolume(server, volume, true).catch(() => undefined);
  }

  if (server?.vmid && volume.diskName) {
    const { conn } = await nodeFor(server);
    try {
      let config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
      let key = keyForVolid(config, volume.diskName);

      // If still mounted, detach to an "unused" entry first.
      if (key && key.startsWith("scsi")) {
        await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
        config = await waitForConfig(conn, server.vmid, (c) => {
          const k = keyForVolid(c, String(volume.diskName));
          return !k || !k.startsWith("scsi");
        });
        key = keyForVolid(config, volume.diskName);
      }
      // Deleting an "unused" entry destroys the underlying disk.
      if (key) {
        await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
      }
    } catch (e: any) {
      const msg = String(e?.body ?? e?.message ?? e);
      if (!msg.includes("does not exist")) throw e;
    }
  }

  await db.volume.delete({ where: { id: volume.id } });
  await notify(volume.userId, `Volume "${volume.name}" deleted`, undefined, "/dashboard/volumes");
}

