/**
 * Is the VM actually running right now?
 *
 * `Server.status` is NOT good enough for this decision: a row can say STOPPED or
 * ERROR while the VM is up (and vice versa), and getting it wrong here means
 * hot-unplugging a mounted filesystem. Proxmox is the ground truth; "unknown" is
 * reported honestly so the caller can refuse instead of assuming.
 */
async function vmRunState(conn: any, vmid: number): Promise<"running" | "stopped" | "unknown"> {
  try {
    const s = await conn.vmStatus(vmid);
    const st = String(s?.status ?? "");
    if (st === "running") return "running";
    if (st) return "stopped";
  } catch (e) {
    console.error(`[volumes] could not read run state of VM ${vmid}`, e);
  }
  return "unknown";
}

